(function () {
  var SUMMARIZE_ENDPOINT = 'https://plain-rice-b16a.johnson35762.workers.dev/summarize';
  var LOCALE_STORAGE_KEY = 'hr_summarize_locale';
  var LOCALE_TAG_MAX = 35;
  var LOCALE_TAG_PATTERN = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;

  function ready(fn) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn);
    else fn();
  }

  function normalizeLocaleTag(s) {
    if (!s || typeof s !== 'string') return '';
    s = s.trim().slice(0, LOCALE_TAG_MAX).split(',')[0].split(';')[0].trim();
    s = s.replace(/_/g, '-').replace(/-+/g, '-');
    if (!LOCALE_TAG_PATTERN.test(s)) return '';
    return s;
  }

  function autoResolvedLocale() {
    var h = normalizeLocaleTag(document.documentElement.getAttribute('lang') || '');
    if (h) return h;
    var nav = (navigator.languages && navigator.languages[0]) || navigator.language || '';
    var n = normalizeLocaleTag(nav);
    return n || 'en';
  }

  function preferredLocaleForRequest() {
    try {
      var st = localStorage.getItem(LOCALE_STORAGE_KEY);
      var n = normalizeLocaleTag(st || '');
      if (n) return n;
    } catch (e) {}
    return autoResolvedLocale();
  }

  /** Prefer the visible language dropdown value so the request matches the UI even if localStorage fails. */
  function localeForApi(sel) {
    var fromSelect = normalizeLocaleTag(sel && sel.value ? sel.value : '');
    if (fromSelect) return fromSelect;
    return preferredLocaleForRequest();
  }

  function postPlainText(el) {
    var clone = el.cloneNode(true);
    var nodes = clone.querySelectorAll('script, style, noscript');
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      if (n.parentNode) n.parentNode.removeChild(n);
    }
    return (clone.textContent || '').replace(/\s+/g, ' ').trim();
  }

  function syncLocaleSelectFromStorage(sel) {
    var norm = '';
    try {
      norm = normalizeLocaleTag(localStorage.getItem(LOCALE_STORAGE_KEY) || '');
    } catch (e) {}
    if (norm) {
      var has = false;
      for (var oi = 0; oi < sel.options.length; oi++) {
        if (sel.options[oi].value === norm) {
          has = true;
          break;
        }
      }
      if (has) sel.value = norm;
      else {
        try {
          localStorage.removeItem(LOCALE_STORAGE_KEY);
        } catch (e2) {}
        sel.value = '';
      }
    } else sel.value = '';
  }

  ready(function () {
    if (!document.body || !document.body.classList.contains('is-post')) return;
    var bodyEl = document.getElementById('post-body');
    if (!bodyEl || !bodyEl.parentNode) return;
    if (bodyEl.parentNode.querySelector('.hr-ai-summarize')) return;

    var MIN_MS_BETWEEN_CALLS = 60000;
    var lastCallEnd = 0;

    var wrap = document.createElement('div');
    wrap.className = 'hr-ai-summarize';
    wrap.setAttribute('role', 'region');
    wrap.setAttribute('aria-label', 'AI summary');
    wrap.innerHTML =
      '<div class="hr-ai-summarize-toolbar">' +
      '<button type="button" class="hr-ai-summarize-btn">AI summarize</button>' +
      '<label class="hr-ai-summarize-locale-label">' +
      'Language ' +
      '<select class="hr-ai-summarize-locale" aria-label="Summary language">' +
      '<option value="">Auto</option>' +
      '<option value="en">English</option>' +
      '<option value="zh-TW">中文（繁體）</option>' +
      '<option value="zh-CN">中文（简体）</option>' +
      '<option value="ja">日本語</option>' +
      '<option value="ko">한국어</option>' +
      '<option value="es">Español</option>' +
      '<option value="fr">Français</option>' +
      '<option value="de">Deutsch</option>' +
      '<option value="pt-BR">Português (BR)</option>' +
      '<option value="vi">Tiếng Việt</option>' +
      '<option value="th">ไทย</option>' +
      '<option value="id">Bahasa Indonesia</option>' +
      '<option value="it">Italiano</option>' +
      '<option value="nl">Nederlands</option>' +
      '<option value="pl">Polski</option>' +
      '<option value="tr">Türkçe</option>' +
      '<option value="ru">Русский</option>' +
      '<option value="ar">العربية</option>' +
      '</select>' +
      '</label>' +
      '</div>' +
      '<div class="hr-ai-summarize-status" aria-live="polite"></div>' +
      '<div class="hr-ai-summarize-out" hidden></div>';

    bodyEl.parentNode.insertBefore(wrap, bodyEl);

    var btn = wrap.querySelector('.hr-ai-summarize-btn');
    var statusEl = wrap.querySelector('.hr-ai-summarize-status');
    var outEl = wrap.querySelector('.hr-ai-summarize-out');
    var localeSelect = wrap.querySelector('.hr-ai-summarize-locale');
    syncLocaleSelectFromStorage(localeSelect);

    localeSelect.addEventListener('change', function () {
      var v = localeSelect.value;
      try {
        if (!v) localStorage.removeItem(LOCALE_STORAGE_KEY);
        else localStorage.setItem(LOCALE_STORAGE_KEY, v);
      } catch (e) {}
    });

    function setBusy(busy) {
      btn.disabled = !!busy;
      btn.textContent = busy ? 'Summarizing…' : 'AI summarize';
      localeSelect.disabled = !!busy;
    }

    btn.addEventListener('click', function () {
      var now = Date.now();
      if (now - lastCallEnd < MIN_MS_BETWEEN_CALLS && lastCallEnd > 0) {
        var waitSec = Math.ceil((MIN_MS_BETWEEN_CALLS - (now - lastCallEnd)) / 1000);
        statusEl.textContent = 'Please wait ' + waitSec + 's before summarizing again (saves API quota).';
        return;
      }

      var text = postPlainText(bodyEl);
      if (!text) {
        statusEl.textContent = 'No post text found to summarize.';
        outEl.hidden = true;
        return;
      }
      statusEl.textContent = '';
      outEl.hidden = true;
      outEl.textContent = '';
      setBusy(true);
      fetch(SUMMARIZE_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: text, locale: localeForApi(localeSelect) }),
      })
        .then(function (res) {
          return res.json().then(function (data) {
            if (!res.ok) {
              var gem =
                data &&
                data.details &&
                data.details.error &&
                data.details.error.message;
              var msg = gem || (data && data.error) || res.statusText || 'Request failed';
              if (res.status === 429) {
                msg =
                  'Summary is temporarily unavailable (Gemini quota or rate limit). Wait a minute and try again, or check billing in Google AI Studio.';
              }
              throw new Error(msg);
            }
            return data;
          });
        })
        .then(function (data) {
          if (!data || !data.summary) throw new Error('Invalid response');
          outEl.textContent = data.summary;
          outEl.hidden = false;
        })
        .catch(function (err) {
          statusEl.textContent = err && err.message ? err.message : 'Summary failed.';
        })
        .finally(function () {
          lastCallEnd = Date.now();
          setBusy(false);
        });
    });
  });
})();
